// SimplInterceptor.js
class SimplInterceptor {
  constructor() {
    this.intercept = (req, res, next) => {
      const { url } = req;
      if (url === '/api/secret') {
        res.status(403).send({
          error: 'Access Denied',
          message: 'You are not authorized to access this resource',
        });
      } else {
        next();
      }
    };
  }
}

export default SimplInterceptor;
